const orig = $('When Called').first().json;
const impact = (orig.impact || '').trim();
const REAL_TIERS = ['Niski','Średni','Wysoki','Krytycznie ważne'];

let row = null;
try { const r = $input.first().json; if (r && r.litellm_model) row = r; } catch (e) {}

let routing_default_used = false;
if (!row) {
  row = { litellm_model: 'haxe-sonnet-4-6-direct', temperature: 0.7, max_tokens: 4000, nudge: null,
          price_in_usd_per_1k: 0.003, price_out_usd_per_1k: 0.015, impact: '__fallback__' };
  if (REAL_TIERS.includes(impact)) routing_default_used = true;
} else if (row.impact === '__default__' && REAL_TIERS.includes(impact)) {
  routing_default_used = true;
}

const nudge = row.nudge ? (row.nudge + '\n\n---\n\n') : '';
const prompt = nudge + (orig.prompt || '');
const pd = (orig.personal_data === true || orig.personal_data === 'true') ? true : false;
const ews = (orig.enable_web_search === false || orig.enable_web_search === 'false') ? 'false' : 'true';

return [{ json: {
  litellm_model: row.litellm_model,
  temperature: (row.temperature != null && row.temperature !== '') ? Number(row.temperature) : null,
  max_tokens: Number(row.max_tokens),
  price_in_usd_per_1k: Number(row.price_in_usd_per_1k || 0),
  price_out_usd_per_1k: Number(row.price_out_usd_per_1k || 0),
  prompt,
  impact,
  personal_data: pd,
  enable_web_search: ews,
  task_type: orig.task_type || '',
  clickup_task_id: orig.clickup_task_id || '',
  triggered_by: orig.triggered_by || 'explicit_command',
  invocation_type: orig.invocation_type || 'explicit',
  caller_user_id: orig.caller_user_id || '',
  process_type: orig.process_type || '',
  routing_default_used
} }];

const r = $('Resolve Routing').first().json;
let rp = null;
try { const row = $input.first().json; if (row && row.max_research_rounds != null) rp = row; } catch (e) {}
const max_research_rounds = (rp && rp.max_research_rounds != null) ? Number(rp.max_research_rounds) : 5;
const tavily_max_results = (rp && rp.tavily_max_results != null) ? Number(rp.tavily_max_results) : 5;
return [{ json: Object.assign({}, r, { max_research_rounds: max_research_rounds, tavily_max_results: tavily_max_results }) }];

const routing = $('Merge Params').first().json;
const mt = $('Call Model Turn').first().json || {};
const completion = mt.completion || '';
const sources = Array.isArray(mt.sources) ? mt.sources : [];
const calls = Array.isArray(mt.calls) ? mt.calls : [];
const web_search_used = mt.web_search_used === true;
const web_search_error = mt.web_search_error === true;
const web_search_error_code = mt.web_search_error_code || '';
const input_tokens = (mt.input_tokens != null) ? Number(mt.input_tokens) : null;
const output_tokens = (mt.output_tokens != null) ? Number(mt.output_tokens) : null;

let fx = null;
try { const f = $('Get FX Rate').first().json.rate; if (f != null && f !== '') fx = Number(f); } catch (e) {}

let usd_cost = (mt.usd_cost != null && mt.usd_cost !== '') ? Number(mt.usd_cost) : null;
let cost_source = 'model_turn_totals';
let cost_missing = false;
if (usd_cost == null || isNaN(usd_cost) || usd_cost === 0) {
  cost_missing = true;
  cost_source = 'fallback_table';
  const pin = Number(routing.price_in_usd_per_1k || 0);
  const pout = Number(routing.price_out_usd_per_1k || 0);
  if (input_tokens != null && output_tokens != null && (pin || pout)) {
    usd_cost = (input_tokens/1000)*pin + (output_tokens/1000)*pout;
  } else { usd_cost = null; }
}
const cost_pln = (usd_cost != null && fx != null) ? Number((usd_cost * fx).toFixed(6)) : null;

const alias = routing.litellm_model || '';
const provider = alias.includes('bedrock') ? 'litellm/bedrock-eu' : 'litellm/anthropic-direct';

return [{ json: {
  completion,
  sources,
  calls,
  web_search_used,
  web_search_error,
  web_search_error_code,
  rounds: (mt.rounds != null ? mt.rounds : null),
  searches: (mt.searches != null ? mt.searches : null),
  model_used: alias,
  provider,
  input_tokens, output_tokens,
  usd_cost, fx_rate: fx, cost_pln,
  cost_source, cost_missing,
  routing_default_used: !!routing.routing_default_used,
  impact: routing.impact,
  personal_data: routing.personal_data,
  task_type: routing.task_type,
  clickup_task_id: routing.clickup_task_id,
  triggered_by: routing.triggered_by,
  invocation_type: routing.invocation_type,
  caller_user_id: routing.caller_user_id,
  process_type: routing.process_type
} }];

const cc = $('Compute Cost').first().json;
let calls = Array.isArray(cc.calls) ? cc.calls : [];
if (!calls.length) { calls = [{ model_used: cc.model_used, input_tokens: cc.input_tokens, output_tokens: cc.output_tokens, usd_cost: cc.usd_cost }]; }
return calls.map(function (c) { return { json: {
  clickup_task_id: cc.clickup_task_id || null,
  caller_user_id: cc.caller_user_id || null,
  process_type: cc.process_type || null,
  triggered_by: cc.triggered_by || 'explicit_command',
  invocation_type: cc.invocation_type || 'explicit',
  impact: cc.impact || null,
  model_used: c.model_used || null,
  input_tokens: (c.input_tokens != null) ? c.input_tokens : null,
  output_tokens: (c.output_tokens != null) ? c.output_tokens : null,
  usd_cost: (c.usd_cost != null) ? c.usd_cost : null
} }; });
